  `payment_method_id` bigint(20) unsigned DEFAULT NULL,
  `numero_operacion` varchar(60) DEFAULT NULL,
  `pago_id` bigint(20) unsigned DEFAULT NULL,
  `fecha_pago` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `enrollment_installments_payment_method_id_foreign` (`payment_method_id`),
  KEY `enrollment_installments_pago_id_foreign` (`pago_id`),
  KEY `enrollment_installments_enrollment_installment_plan_id_index` (`enrollment_installment_plan_id`),
  KEY `enrollment_installments_estado_fecha_vencimiento_index` (`estado`,`fecha_vencimiento`),
  KEY `enrollment_installments_cliente_matricula_id_index` (`cliente_matricula_id`),
  CONSTRAINT `enrollment_installments_cliente_matricula_id_foreign` FOREIGN KEY (`cliente_matricula_id`) REFERENCES `cliente_matriculas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `enrollment_installments_enrollment_installment_plan_id_foreign` FOREIGN KEY (`enrollment_installment_plan_id`) REFERENCES `enrollment_installment_plans` (`id`) ON DELETE CASCADE,
  CONSTRAINT `enrollment_installments_pago_id_foreign` FOREIGN KEY (`pago_id`) REFERENCES `pagos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `enrollment_installments_payment_method_id_foreign` FOREIGN KEY (`payment_method_id`) REFERENCES `payment_methods` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para evaluaciones_medidas_nutricion
-- --------------------------------------------------------
DROP TABLE IF EXISTS `evaluaciones_medidas_nutricion`;
CREATE TABLE `evaluaciones_medidas_nutricion` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `cliente_id` bigint(20) unsigned NOT NULL,
  `peso` decimal(5,2) DEFAULT NULL,
  `estatura` decimal(5,2) DEFAULT NULL,
  `imc` decimal(5,2) DEFAULT NULL,
  `porcentaje_grasa` decimal(5,2) DEFAULT NULL,
  `porcentaje_musculo` decimal(5,2) DEFAULT NULL,
  `masa_muscular` decimal(5,2) DEFAULT NULL,
  `masa_grasa` decimal(5,2) DEFAULT NULL,
  `masa_osea` decimal(5,2) DEFAULT NULL,
  `masa_residual` decimal(5,2) DEFAULT NULL,
  `circunferencias` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`circunferencias`)),
  `presion_arterial` varchar(20) DEFAULT NULL,
  `frecuencia_cardiaca` int(11) DEFAULT NULL,
  `objetivo` varchar(255) DEFAULT NULL,
  `nutricionista_id` bigint(20) unsigned DEFAULT NULL,
  `fecha_proxima_evaluacion` date DEFAULT NULL,
  `estado` enum('pendiente','completada','cancelada') NOT NULL DEFAULT 'completada',
  `observaciones` text DEFAULT NULL,
  `evaluado_por` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `evaluaciones_medidas_nutricion_cliente_id_index` (`cliente_id`),
  KEY `evaluaciones_medidas_nutricion_evaluado_por_index` (`evaluado_por`),
  KEY `evaluaciones_medidas_nutricion_nutricionista_id_index` (`nutricionista_id`),
  KEY `evaluaciones_medidas_nutricion_fecha_proxima_evaluacion_index` (`fecha_proxima_evaluacion`),
  KEY `evaluaciones_medidas_nutricion_estado_index` (`estado`),
  KEY `evaluaciones_medidas_nutricion_created_at_index` (`created_at`),
  CONSTRAINT `evaluaciones_medidas_nutricion_cliente_id_foreign` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`),
  CONSTRAINT `evaluaciones_medidas_nutricion_evaluado_por_foreign` FOREIGN KEY (`evaluado_por`) REFERENCES `users` (`id`),
  CONSTRAINT `evaluaciones_medidas_nutricion_nutricionista_id_foreign` FOREIGN KEY (`nutricionista_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para exercise_relations
-- --------------------------------------------------------
DROP TABLE IF EXISTS `exercise_relations`;
CREATE TABLE `exercise_relations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `exercise_id` bigint(20) unsigned NOT NULL,
  `related_exercise_id` bigint(20) unsigned NOT NULL,
  `relation_type` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ex_relations_unique` (`exercise_id`,`related_exercise_id`,`relation_type`),
  KEY `exercise_relations_related_exercise_id_foreign` (`related_exercise_id`),
  CONSTRAINT `exercise_relations_exercise_id_foreign` FOREIGN KEY (`exercise_id`) REFERENCES `exercises` (`id`) ON DELETE CASCADE,
  CONSTRAINT `exercise_relations_related_exercise_id_foreign` FOREIGN KEY (`related_exercise_id`) REFERENCES `exercises` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para exercises
-- --------------------------------------------------------
DROP TABLE IF EXISTS `exercises`;
CREATE TABLE `exercises` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(255) NOT NULL,
  `grupo_muscular_principal` varchar(255) DEFAULT NULL,
  `musculos_secundarios` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`musculos_secundarios`)),
  `tipo` varchar(255) NOT NULL,
  `nivel` varchar(255) DEFAULT NULL,
  `equipamiento` varchar(255) DEFAULT NULL,
  `descripcion_tecnica` text DEFAULT NULL,
  `errores_comunes` text DEFAULT NULL,
  `consejos_seguridad` text DEFAULT NULL,
  `video_url` varchar(255) DEFAULT NULL,
  `estado` varchar(255) NOT NULL DEFAULT 'activo',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `exercises_estado_index` (`estado`),
  KEY `exercises_tipo_index` (`tipo`),
  KEY `exercises_grupo_muscular_principal_index` (`grupo_muscular_principal`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para failed_jobs
-- --------------------------------------------------------
DROP TABLE IF EXISTS `failed_jobs`;
CREATE TABLE `failed_jobs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` varchar(255) NOT NULL,
  `connection` text NOT NULL,
  `queue` text NOT NULL,
  `payload` longtext NOT NULL,
  `exception` longtext NOT NULL,
  `failed_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `failed_jobs_uuid_unique` (`uuid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para gym_settings
-- --------------------------------------------------------
DROP TABLE IF EXISTS `gym_settings`;
CREATE TABLE `gym_settings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `nombre_gimnasio` varchar(200) NOT NULL,
  `ruc` varchar(20) DEFAULT NULL,
  `direccion` text DEFAULT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `logo` varchar(255) DEFAULT NULL,
  `horarios_acceso` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`horarios_acceso`)),
  `politicas_acceso` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para health_records
-- --------------------------------------------------------
DROP TABLE IF EXISTS `health_records`;
CREATE TABLE `health_records` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `cliente_id` bigint(20) unsigned NOT NULL,
  `enfermedades` text DEFAULT NULL,
