  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `movimientos_inventario_usuario_id_foreign` (`usuario_id`),
  KEY `movimientos_inventario_producto_id_index` (`producto_id`),
  KEY `movimientos_inventario_tipo_index` (`tipo`),
  KEY `movimientos_inventario_fecha_index` (`fecha`),
  KEY `movimientos_inventario_referencia_tipo_referencia_id_index` (`referencia_tipo`,`referencia_id`),
  CONSTRAINT `movimientos_inventario_producto_id_foreign` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`id`),
  CONSTRAINT `movimientos_inventario_usuario_id_foreign` FOREIGN KEY (`usuario_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para nutrition_goal_progress
-- --------------------------------------------------------
DROP TABLE IF EXISTS `nutrition_goal_progress`;
CREATE TABLE `nutrition_goal_progress` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `nutrition_goal_id` bigint(20) unsigned NOT NULL,
  `fecha` date NOT NULL,
  `peso` decimal(5,2) DEFAULT NULL,
  `medidas` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`medidas`)),
  `observaciones` text DEFAULT NULL,
  `fotos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'rutas de archivos' CHECK (json_valid(`fotos`)),
  `adherencia` varchar(40) DEFAULT NULL,
  `progreso_general` text DEFAULT NULL,
  `registrado_por` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `nutrition_goal_progress_registrado_por_foreign` (`registrado_por`),
  KEY `nutrition_goal_progress_nutrition_goal_id_index` (`nutrition_goal_id`),
  KEY `nutrition_goal_progress_fecha_index` (`fecha`),
  CONSTRAINT `nutrition_goal_progress_nutrition_goal_id_foreign` FOREIGN KEY (`nutrition_goal_id`) REFERENCES `nutrition_goals` (`id`) ON DELETE CASCADE,
  CONSTRAINT `nutrition_goal_progress_registrado_por_foreign` FOREIGN KEY (`registrado_por`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para nutrition_goals
-- --------------------------------------------------------
DROP TABLE IF EXISTS `nutrition_goals`;
CREATE TABLE `nutrition_goals` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `cliente_id` bigint(20) unsigned NOT NULL,
  `trainer_user_id` bigint(20) unsigned NOT NULL,
  `objetivo` varchar(60) NOT NULL COMMENT 'bajar_grasa, ganar_masa, mejorar_resistencia, mejorar_salud, mantener_peso, personalizado',
  `objetivo_personalizado` varchar(200) DEFAULT NULL,
  `fecha_inicio` date NOT NULL,
  `fecha_objetivo` date DEFAULT NULL,
  `observaciones` text DEFAULT NULL,
  `estado` varchar(20) NOT NULL DEFAULT 'activo' COMMENT 'activo, cumplido, cancelado',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `nutrition_goals_cliente_id_index` (`cliente_id`),
  KEY `nutrition_goals_trainer_user_id_index` (`trainer_user_id`),
  KEY `nutrition_goals_estado_index` (`estado`),
  CONSTRAINT `nutrition_goals_cliente_id_foreign` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`),
  CONSTRAINT `nutrition_goals_trainer_user_id_foreign` FOREIGN KEY (`trainer_user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para pagos
-- --------------------------------------------------------
DROP TABLE IF EXISTS `pagos`;
CREATE TABLE `pagos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
