  `moneda` varchar(3) NOT NULL DEFAULT 'PEN',
  `metodo_pago` varchar(50) NOT NULL,
  `numero_operacion` varchar(60) DEFAULT NULL,
  `entidad_financiera` varchar(100) DEFAULT NULL,
  `fecha_pago` datetime NOT NULL,
  `es_pago_parcial` tinyint(1) NOT NULL DEFAULT 0,
  `saldo_pendiente` decimal(10,2) NOT NULL DEFAULT 0.00,
  `comprobante_tipo` varchar(255) DEFAULT NULL,
  `comprobante_numero` varchar(255) DEFAULT NULL,
  `registrado_por` bigint(20) unsigned NOT NULL,
  `caja_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pagos_registrado_por_foreign` (`registrado_por`),
  KEY `pagos_cliente_id_index` (`cliente_id`),
  KEY `pagos_cliente_membresia_id_index` (`cliente_membresia_id`),
  KEY `pagos_fecha_pago_index` (`fecha_pago`),
  KEY `pagos_metodo_pago_index` (`metodo_pago`),
  KEY `pagos_caja_id_index` (`caja_id`),
  KEY `pagos_cliente_matricula_id_index` (`cliente_matricula_id`),
  KEY `pagos_payment_method_id_index` (`payment_method_id`),
  CONSTRAINT `pagos_caja_id_foreign` FOREIGN KEY (`caja_id`) REFERENCES `cajas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pagos_cliente_id_foreign` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`),
  CONSTRAINT `pagos_cliente_matricula_id_foreign` FOREIGN KEY (`cliente_matricula_id`) REFERENCES `cliente_matriculas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pagos_cliente_membresia_id_foreign` FOREIGN KEY (`cliente_membresia_id`) REFERENCES `cliente_membresias` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pagos_payment_method_id_foreign` FOREIGN KEY (`payment_method_id`) REFERENCES `payment_methods` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pagos_registrado_por_foreign` FOREIGN KEY (`registrado_por`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2533 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para password_reset_tokens
-- --------------------------------------------------------
DROP TABLE IF EXISTS `password_reset_tokens`;
CREATE TABLE `password_reset_tokens` (
  `email` varchar(255) NOT NULL,
  `token` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para payment_methods
