-- --------------------------------------------------------
-- Estructura de tabla para permissions
-- --------------------------------------------------------
DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `guard_name` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `permissions_name_guard_name_unique` (`name`,`guard_name`)
) ENGINE=InnoDB AUTO_INCREMENT=94 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para productos
-- --------------------------------------------------------
DROP TABLE IF EXISTS `productos`;
CREATE TABLE `productos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `codigo` varchar(255) NOT NULL,
  `nombre` varchar(255) NOT NULL,
  `descripcion` text DEFAULT NULL,
  `categoria_id` bigint(20) unsigned DEFAULT NULL,
  `precio_venta` decimal(10,2) NOT NULL,
  `precio_compra` decimal(10,2) NOT NULL DEFAULT 0.00,
  `stock_actual` int(11) NOT NULL DEFAULT 0,
  `stock_minimo` int(11) NOT NULL DEFAULT 0,
  `unidad_medida` varchar(20) NOT NULL DEFAULT 'unidad',
  `imagen` varchar(255) DEFAULT NULL,
  `estado` enum('activo','inactivo') NOT NULL DEFAULT 'activo',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `productos_codigo_unique` (`codigo`),
  KEY `productos_codigo_index` (`codigo`),
  KEY `productos_categoria_id_index` (`categoria_id`),
  KEY `productos_estado_index` (`estado`),
  KEY `productos_stock_actual_index` (`stock_actual`),
  CONSTRAINT `productos_categoria_id_foreign` FOREIGN KEY (`categoria_id`) REFERENCES `categorias_productos` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para rentable_space_rates
-- --------------------------------------------------------
DROP TABLE IF EXISTS `rentable_space_rates`;
CREATE TABLE `rentable_space_rates` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `rentable_space_id` bigint(20) unsigned NOT NULL,
  `tipo_tarifa` varchar(30) NOT NULL DEFAULT 'por_hora',
  `nombre` varchar(100) DEFAULT NULL,
  `precio` decimal(12,2) NOT NULL,
  `hora_inicio` time DEFAULT NULL,
  `hora_fin` time DEFAULT NULL,
  `dia_semana` tinyint(3) unsigned DEFAULT NULL,
  `fecha_especial` date DEFAULT NULL,
  `sede_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rentable_space_rates_rentable_space_id_index` (`rentable_space_id`),
  CONSTRAINT `rentable_space_rates_rentable_space_id_foreign` FOREIGN KEY (`rentable_space_id`) REFERENCES `rentable_spaces` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para rentable_spaces
-- --------------------------------------------------------
DROP TABLE IF EXISTS `rentable_spaces`;
CREATE TABLE `rentable_spaces` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(255) NOT NULL,
  `descripcion` text DEFAULT NULL,
  `capacidad` int(10) unsigned DEFAULT NULL,
  `estado` varchar(20) NOT NULL DEFAULT 'activo',
  `color_calendario` varchar(20) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rentable_spaces_estado_index` (`estado`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para rental_payments
-- --------------------------------------------------------
DROP TABLE IF EXISTS `rental_payments`;
CREATE TABLE `rental_payments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `rental_id` bigint(20) unsigned NOT NULL,
  `monto` decimal(12,2) NOT NULL,
  `payment_method_id` bigint(20) unsigned DEFAULT NULL,
  `numero_operacion` varchar(60) DEFAULT NULL,
  `entidad_financiera` varchar(80) DEFAULT NULL,
  `fecha_pago` date NOT NULL,
  `caja_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rental_payments_payment_method_id_foreign` (`payment_method_id`),
  KEY `rental_payments_caja_id_foreign` (`caja_id`),
  KEY `rental_payments_rental_id_index` (`rental_id`),
  CONSTRAINT `rental_payments_caja_id_foreign` FOREIGN KEY (`caja_id`) REFERENCES `cajas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rental_payments_payment_method_id_foreign` FOREIGN KEY (`payment_method_id`) REFERENCES `payment_methods` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rental_payments_rental_id_foreign` FOREIGN KEY (`rental_id`) REFERENCES `rentals` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para rentals
-- --------------------------------------------------------
DROP TABLE IF EXISTS `rentals`;
CREATE TABLE `rentals` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `rentable_space_id` bigint(20) unsigned NOT NULL,
  `cliente_id` bigint(20) unsigned DEFAULT NULL,
  `nombre_externo` varchar(120) DEFAULT NULL,
  `documento_externo` varchar(30) DEFAULT NULL,
  `fecha` date NOT NULL,
  `hora_inicio` time NOT NULL,
  `hora_fin` time NOT NULL,
  `precio` decimal(12,2) NOT NULL,
  `estado` varchar(20) NOT NULL DEFAULT 'reservado',
  `descuento` decimal(12,2) NOT NULL DEFAULT 0.00,
  `discount_coupon_id` bigint(20) unsigned DEFAULT NULL,
  `observaciones` text DEFAULT NULL,
  `registrado_por` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rentals_cliente_id_foreign` (`cliente_id`),
  KEY `rentals_discount_coupon_id_foreign` (`discount_coupon_id`),
  KEY `rentals_registrado_por_foreign` (`registrado_por`),
  KEY `rentals_rentable_space_id_fecha_index` (`rentable_space_id`,`fecha`),
  KEY `rentals_fecha_estado_index` (`fecha`,`estado`),
  CONSTRAINT `rentals_cliente_id_foreign` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rentals_discount_coupon_id_foreign` FOREIGN KEY (`discount_coupon_id`) REFERENCES `discount_coupons` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rentals_registrado_por_foreign` FOREIGN KEY (`registrado_por`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rentals_rentable_space_id_foreign` FOREIGN KEY (`rentable_space_id`) REFERENCES `rentable_spaces` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para role_has_permissions
-- --------------------------------------------------------
DROP TABLE IF EXISTS `role_has_permissions`;
CREATE TABLE `role_has_permissions` (
  `permission_id` bigint(20) unsigned NOT NULL,
  `role_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`permission_id`,`role_id`),
  KEY `role_has_permissions_role_id_foreign` (`role_id`),
  CONSTRAINT `role_has_permissions_permission_id_foreign` FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `role_has_permissions_role_id_foreign` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para roles
-- --------------------------------------------------------
DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `guard_name` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `roles_name_guard_name_unique` (`name`,`guard_name`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para routine_template_day_exercises
-- --------------------------------------------------------
DROP TABLE IF EXISTS `routine_template_day_exercises`;
CREATE TABLE `routine_template_day_exercises` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `routine_template_day_id` bigint(20) unsigned NOT NULL,
  `exercise_id` bigint(20) unsigned NOT NULL,
  `series` int(10) unsigned NOT NULL DEFAULT 3,
  `repeticiones` varchar(255) DEFAULT NULL,
  `descanso_segundos` int(10) unsigned DEFAULT NULL,
  `tempo` varchar(255) DEFAULT NULL,
  `intensidad_rpe` varchar(255) DEFAULT NULL,
  `metodo` varchar(255) NOT NULL DEFAULT 'normal',
  `notas` text DEFAULT NULL,
  `orden` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `routine_template_day_exercises_exercise_id_foreign` (`exercise_id`),
  KEY `rtde_day_orden` (`routine_template_day_id`,`orden`),
  CONSTRAINT `routine_template_day_exercises_exercise_id_foreign` FOREIGN KEY (`exercise_id`) REFERENCES `exercises` (`id`),
  CONSTRAINT `routine_template_day_exercises_routine_template_day_id_foreign` FOREIGN KEY (`routine_template_day_id`) REFERENCES `routine_template_days` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para routine_template_days
-- --------------------------------------------------------
DROP TABLE IF EXISTS `routine_template_days`;
CREATE TABLE `routine_template_days` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `routine_template_id` bigint(20) unsigned NOT NULL,
  `nombre` varchar(255) NOT NULL,
  `orden` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `routine_template_days_routine_template_id_index` (`routine_template_id`),
  CONSTRAINT `routine_template_days_routine_template_id_foreign` FOREIGN KEY (`routine_template_id`) REFERENCES `routine_templates` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para routine_templates
-- --------------------------------------------------------
DROP TABLE IF EXISTS `routine_templates`;
CREATE TABLE `routine_templates` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(255) NOT NULL,
  `objetivo` varchar(255) DEFAULT NULL,
  `nivel` varchar(255) DEFAULT NULL,
  `duracion_semanas` int(10) unsigned DEFAULT NULL,
  `frecuencia_dias_semana` int(10) unsigned DEFAULT NULL,
  `descripcion` text DEFAULT NULL,
  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tags`)),
  `estado` varchar(255) NOT NULL DEFAULT 'borrador',
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `routine_templates_created_by_foreign` (`created_by`),
  CONSTRAINT `routine_templates_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para seguimientos_nutricion
-- --------------------------------------------------------
DROP TABLE IF EXISTS `seguimientos_nutricion`;
CREATE TABLE `seguimientos_nutricion` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `cliente_id` bigint(20) unsigned NOT NULL,
  `nutricionista_id` bigint(20) unsigned DEFAULT NULL,
  `cita_id` bigint(20) unsigned DEFAULT NULL,
  `tipo` enum('plan_inicial','seguimiento','recomendacion','incidencia','experiencia') NOT NULL DEFAULT 'seguimiento',
  `fecha` date NOT NULL,
  `objetivo` varchar(255) DEFAULT NULL,
  `calorias_objetivo` int(10) unsigned DEFAULT NULL,
  `macros` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'proteina, grasa, carbohidratos' CHECK (json_valid(`macros`)),
  `contenido` text DEFAULT NULL,
  `estado` enum('borrador','activo','archivado') NOT NULL DEFAULT 'activo',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `seguimientos_nutricion_cliente_id_index` (`cliente_id`),
  KEY `seguimientos_nutricion_nutricionista_id_index` (`nutricionista_id`),
  KEY `seguimientos_nutricion_cita_id_index` (`cita_id`),
  KEY `seguimientos_nutricion_fecha_index` (`fecha`),
  KEY `seguimientos_nutricion_tipo_index` (`tipo`),
  CONSTRAINT `seguimientos_nutricion_cita_id_foreign` FOREIGN KEY (`cita_id`) REFERENCES `citas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `seguimientos_nutricion_cliente_id_foreign` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`),
  CONSTRAINT `seguimientos_nutricion_nutricionista_id_foreign` FOREIGN KEY (`nutricionista_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para servicios_externos
-- --------------------------------------------------------
DROP TABLE IF EXISTS `servicios_externos`;
CREATE TABLE `servicios_externos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `codigo` varchar(255) NOT NULL,
  `nombre` varchar(255) NOT NULL,
  `descripcion` text DEFAULT NULL,
  `categoria_id` bigint(20) unsigned DEFAULT NULL,
  `precio` decimal(10,2) NOT NULL,
  `duracion_minutos` int(11) DEFAULT NULL,
  `estado` enum('activo','inactivo') NOT NULL DEFAULT 'activo',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `servicios_externos_codigo_unique` (`codigo`),
  KEY `servicios_externos_codigo_index` (`codigo`),
  KEY `servicios_externos_categoria_id_index` (`categoria_id`),
  KEY `servicios_externos_estado_index` (`estado`),
  CONSTRAINT `servicios_externos_categoria_id_foreign` FOREIGN KEY (`categoria_id`) REFERENCES `categorias_servicios` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para sessions
-- --------------------------------------------------------
DROP TABLE IF EXISTS `sessions`;
CREATE TABLE `sessions` (
  `id` varchar(255) NOT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `payload` longtext NOT NULL,
  `last_activity` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `sessions_user_id_index` (`user_id`),
  KEY `sessions_last_activity_index` (`last_activity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para tags
-- --------------------------------------------------------
DROP TABLE IF EXISTS `tags`;
CREATE TABLE `tags` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(60) NOT NULL,
  `color` varchar(20) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tags_nombre_unique` (`nombre`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para users
-- --------------------------------------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `estado` varchar(255) NOT NULL DEFAULT 'activo',
  `appearance` varchar(20) DEFAULT 'system',
  `accent` varchar(20) DEFAULT 'neutral',
  `sidebar_bg` varchar(20) DEFAULT 'default',
  `header_bg` varchar(20) DEFAULT 'default',
  `body_bg` varchar(20) DEFAULT 'default',
  `font_size` varchar(20) DEFAULT 'base',
  `appearance_sidebar` varchar(20) DEFAULT 'system',
  `appearance_header` varchar(20) DEFAULT 'system',
  `two_factor_secret` text DEFAULT NULL,
  `two_factor_recovery_codes` text DEFAULT NULL,
  `two_factor_confirmed_at` timestamp NULL DEFAULT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- --------------------------------------------------------
-- Estructura de tabla para venta_items
-- --------------------------------------------------------
DROP TABLE IF EXISTS `venta_items`;
CREATE TABLE `venta_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `venta_id` bigint(20) unsigned NOT NULL,
  `tipo_item` enum('producto','servicio','clase') NOT NULL,
  `item_id` bigint(20) unsigned NOT NULL,
  `nombre_item` varchar(255) NOT NULL,
  `cantidad` int(11) NOT NULL,
  `precio_unitario` decimal(10,2) NOT NULL,
  `descuento` decimal(10,2) NOT NULL DEFAULT 0.00,
  `subtotal` decimal(10,2) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `venta_items_venta_id_index` (`venta_id`),
  KEY `venta_items_tipo_item_item_id_index` (`tipo_item`,`item_id`),
  CONSTRAINT `venta_items_venta_id_foreign` FOREIGN KEY (`venta_id`) REFERENCES `ventas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para ventas
-- --------------------------------------------------------
DROP TABLE IF EXISTS `ventas`;
CREATE TABLE `ventas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `numero_venta` varchar(255) NOT NULL,
  `cliente_id` bigint(20) unsigned DEFAULT NULL,
  `employee_id` bigint(20) unsigned DEFAULT NULL,
  `cliente_venta_nombre` varchar(255) DEFAULT NULL,
  `cliente_venta_documento` varchar(255) DEFAULT NULL,
  `cliente_venta_telefono` varchar(255) DEFAULT NULL,
  `caja_id` bigint(20) unsigned NOT NULL,
  `usuario_id` bigint(20) unsigned NOT NULL,
  `tipo_comprobante` enum('ticket','boleta','factura') DEFAULT 'ticket',
  `numero_comprobante` varchar(255) DEFAULT NULL,
  `serie_comprobante` varchar(255) DEFAULT NULL,
  `subtotal` decimal(10,2) NOT NULL,
  `descuento` decimal(10,2) NOT NULL DEFAULT 0.00,
  `igv` decimal(10,2) NOT NULL DEFAULT 0.00,
  `total` decimal(10,2) NOT NULL,
  `metodo_pago` varchar(50) NOT NULL,
  `payment_method_id` bigint(20) unsigned DEFAULT NULL,
  `numero_operacion` varchar(60) DEFAULT NULL,
  `entidad_financiera` varchar(100) DEFAULT NULL,
  `discount_coupon_id` bigint(20) unsigned DEFAULT NULL,
  `monto_descuento_cupon` decimal(10,2) NOT NULL DEFAULT 0.00,
  `estado` enum('pendiente','completada','anulada') NOT NULL DEFAULT 'completada',
  `fecha_venta` datetime NOT NULL,
  `observaciones` text DEFAULT NULL,
  `es_credito` tinyint(1) NOT NULL DEFAULT 0,
  `monto_inicial` decimal(10,2) DEFAULT NULL,
  `fecha_vencimiento_deuda` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ventas_numero_venta_unique` (`numero_venta`),
  KEY `ventas_numero_venta_index` (`numero_venta`),
  KEY `ventas_cliente_id_index` (`cliente_id`),
  KEY `ventas_caja_id_index` (`caja_id`),
  KEY `ventas_usuario_id_index` (`usuario_id`),
  KEY `ventas_fecha_venta_index` (`fecha_venta`),
  KEY `ventas_estado_index` (`estado`),
  KEY `ventas_tipo_comprobante_index` (`tipo_comprobante`),
  KEY `ventas_payment_method_id_index` (`payment_method_id`),
  KEY `ventas_discount_coupon_id_foreign` (`discount_coupon_id`),
  KEY `ventas_employee_id_foreign` (`employee_id`),
  CONSTRAINT `ventas_caja_id_foreign` FOREIGN KEY (`caja_id`) REFERENCES `cajas` (`id`),
  CONSTRAINT `ventas_cliente_id_foreign` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ventas_discount_coupon_id_foreign` FOREIGN KEY (`discount_coupon_id`) REFERENCES `discount_coupons` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ventas_employee_id_foreign` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ventas_payment_method_id_foreign` FOREIGN KEY (`payment_method_id`) REFERENCES `payment_methods` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ventas_usuario_id_foreign` FOREIGN KEY (`usuario_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para workout_session_exercises
-- --------------------------------------------------------
DROP TABLE IF EXISTS `workout_session_exercises`;
CREATE TABLE `workout_session_exercises` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `workout_session_id` bigint(20) unsigned NOT NULL,
  `exercise_id` bigint(20) unsigned NOT NULL,
  `client_routine_day_exercise_id` bigint(20) unsigned DEFAULT NULL,
  `orden` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `workout_session_exercises_exercise_id_foreign` (`exercise_id`),
  KEY `workout_session_exercises_client_routine_day_exercise_id_foreign` (`client_routine_day_exercise_id`),
  KEY `workout_session_exercises_workout_session_id_index` (`workout_session_id`),
  CONSTRAINT `workout_session_exercises_client_routine_day_exercise_id_foreign` FOREIGN KEY (`client_routine_day_exercise_id`) REFERENCES `client_routine_day_exercises` (`id`) ON DELETE SET NULL,
  CONSTRAINT `workout_session_exercises_exercise_id_foreign` FOREIGN KEY (`exercise_id`) REFERENCES `exercises` (`id`),
  CONSTRAINT `workout_session_exercises_workout_session_id_foreign` FOREIGN KEY (`workout_session_id`) REFERENCES `workout_sessions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Estructura de tabla para workout_session_sets
-- --------------------------------------------------------
DROP TABLE IF EXISTS `workout_session_sets`;
CREATE TABLE `workout_session_sets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `workout_session_exercise_id` bigint(20) unsigned NOT NULL,
  `set_numero` int(10) unsigned NOT NULL,
  `peso` decimal(8,2) DEFAULT NULL,
  `repeticiones` int(10) unsigned DEFAULT NULL,
  `rpe` decimal(4,1) DEFAULT NULL,
  `notas` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `workout_session_sets_workout_session_exercise_id_index` (`workout_session_exercise_id`),
