DROP TABLE IF EXISTS `workout_sessions`;
CREATE TABLE `workout_sessions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `client_routine_id` bigint(20) unsigned NOT NULL,
  `client_routine_day_id` bigint(20) unsigned DEFAULT NULL,
  `fecha_hora` datetime NOT NULL,
  `estado` varchar(255) NOT NULL DEFAULT 'iniciada',
  `notas` text DEFAULT NULL,
  `registrado_por` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `workout_sessions_client_routine_day_id_foreign` (`client_routine_day_id`),
  KEY `workout_sessions_registrado_por_foreign` (`registrado_por`),
  KEY `workout_sessions_client_routine_id_index` (`client_routine_id`),
  KEY `workout_sessions_fecha_hora_index` (`fecha_hora`),
  CONSTRAINT `workout_sessions_client_routine_day_id_foreign` FOREIGN KEY (`client_routine_day_id`) REFERENCES `client_routine_days` (`id`) ON DELETE SET NULL,
  CONSTRAINT `workout_sessions_client_routine_id_foreign` FOREIGN KEY (`client_routine_id`) REFERENCES `client_routines` (`id`) ON DELETE CASCADE,
  CONSTRAINT `workout_sessions_registrado_por_foreign` FOREIGN KEY (`registrado_por`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

