INSERT INTO `gym_settings` (`id`, `nombre_gimnasio`, `ruc`, `direccion`, `telefono`, `email`, `logo`, `horarios_acceso`, `politicas_acceso`, `created_at`, `updated_at`) VALUES (1, 'Gimnasio Fitness Pro', '20123456789', 'Av. Principal 123, Lima, Perú', '+51 987 654 321', 'info@gimnasiofitnesspro.com', NULL, '{\"lunes\":{\"apertura\":\"06:00\",\"cierre\":\"22:00\"},\"martes\":{\"apertura\":\"06:00\",\"cierre\":\"22:00\"},\"miercoles\":{\"apertura\":\"06:00\",\"cierre\":\"22:00\"},\"jueves\":{\"apertura\":\"06:00\",\"cierre\":\"22:00\"},\"viernes\":{\"apertura\":\"06:00\",\"cierre\":\"22:00\"},\"sabado\":{\"apertura\":\"08:00\",\"cierre\":\"20:00\"},\"domingo\":{\"apertura\":\"08:00\",\"cierre\":\"18:00\"}}', '1. Los clientes deben presentar su identificación al ingresar.\n2. El acceso está permitido solo durante el horario establecido.\n3. Se requiere membresía activa para ingresar.\n4. Los menores de 16 años deben estar acompañados por un adulto.\n5. Se prohíbe el uso de teléfonos móviles en las áreas de entrenamiento.\n6. Es obligatorio el uso de toalla y calzado deportivo.\n7. Los clientes deben limpiar el equipo después de usarlo.\n8. Se reserva el derecho de admisión.', '2026-04-01 22:34:59', '2026-04-01 22:34:59');
